from __future__ import annotations


import os


BUILD_PREFIX = "CURATION V1 · build"

BUILD_MARKER = f"{BUILD_PREFIX} {os.environ.get('RAMBLA_BUILD_TOKEN', 'development')}"

BUILD_SENTINEL_PREFIX = "CURATION-V1-build-"


def phrase_status(selection: list[str] | str | None, has_error: bool) -> str:

    if has_error: return "Error"

    if selection == "NO_BROLL": return "NO BROLL"

    return "Selected" if isinstance(selection, list) and selection else "Needs Choice"


def remaining_decisions(chunk_ids: list[str], selections: dict[str, list[str] | str]) -> int:

    return sum(phrase_status(selections.get(cid), False) == "Needs Choice" for cid in chunk_ids)


def move_selection(asset_ids: list[str], index: int, delta: int) -> list[str]:

    result = list(asset_ids); target = index + delta

    if 0 <= index < len(result) and 0 <= target < len(result):

        result[index], result[target] = result[target], result[index]

    return result


def render_curation_page(build_token: str | None = None) -> str:

    marker = f"{BUILD_PREFIX} {build_token or os.environ.get('RAMBLA_BUILD_TOKEN', 'development')}"

    sentinel = f"{BUILD_SENTINEL_PREFIX}{build_token or os.environ.get('RAMBLA_BUILD_TOKEN', 'development')}"

    return '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="rambla-build" content="__BUILD_SENTINEL__"><title>RAMBLA Curation</title>

<style>:root{--bg:#0b0e12;--p:#121821;--line:#293645;--ink:#edf2f7;--muted:#99a8b8;--lime:#d8ff5b}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px Inter,system-ui}main{max-width:1600px;margin:auto;padding:20px}.top,.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.top{justify-content:space-between}.panel,.rail,.stage,.tray{background:var(--p);border:1px solid var(--line);border-radius:12px;padding:14px}.panel{margin-top:14px}.grid{display:grid;grid-template-columns:270px minmax(0,1fr) 310px;gap:14px;margin-top:14px}.muted,small{color:var(--muted)}button,input{font:inherit}button{background:#202b37;color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:9px 12px;font-weight:700;cursor:pointer}button.primary,button.active{background:var(--lime);color:#101319}button:disabled{opacity:.45;cursor:not-allowed}#drop{min-height:76px;border:1px dashed #526579;border-radius:10px;padding:12px}#drop.drag{border-color:var(--lime)}#source{width:min(420px,100%);max-height:240px}.phrase{display:block;width:100%;text-align:left;margin:5px 0}.phrase small{display:block}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}.card{border:1px solid var(--line);border-radius:9px;overflow:hidden}.card video,.card img{width:100%;height:120px;object-fit:cover;background:#202b37;cursor:zoom-in}.copy{padding:9px}.copy small{display:block}.chip{display:flex;align-items:center;gap:5px;border:1px solid var(--lime);border-radius:9px;padding:6px;margin:5px 0}dialog{background:#111923;color:var(--ink)}dialog img,dialog video{max-width:88vw;max-height:82vh}@media(max-width:900px){.grid{grid-template-columns:1fr}}.analysis-split{display:grid;grid-template-columns:1fr 1fr;gap:14px;height:370px;margin-top:12px}.analysis-scroll{overflow:auto;min-width:0;padding:8px;background:#0b0e12;white-space:normal;overflow-wrap:anywhere}.analysis-scroll pre{white-space:pre-wrap;max-height:140px;overflow:auto}#liveLog{font:12px ui-monospace,monospace}#liveLog details{border-bottom:1px solid var(--line);padding:5px}#liveLog summary{cursor:pointer}@media(max-width:700px){.analysis-split{grid-template-columns:1fr;height:500px}}</style>

<main><header class="top"><div><h1>RAMBLA Curation</h1><b>__BUILD_MARKER__</b><div class="muted">Professional editorial workspace · Resolve calls = 0</div></div><b id="save">Ready</b></header>

<section class="panel"><h2>New Reel</h2><div id="drop" class="row"><input id="file" type="file" accept="video/*"><button id="choose">Choose Video</button><button id="path">Open Local Path</button><input id="local" hidden placeholder="Authorized local video path"><button id="loadPath" hidden>Load Path</button><button id="analyze" class="primary" disabled>ANALYZE REEL</button><button id="findVideos" disabled>FIND B-ROLL</button><button id="findImages" disabled>FIND IMAGES</button><button id="stop" hidden>STOP</button><span id="runStatus" class="muted"></span></div><div class="row"><video id="source" controls hidden></video><span id="metadata" class="muted">No source loaded.</span><button id="originalGuide" disabled>Use Original Audio</button><button id="replaceGuide" disabled>Replace Guide Audio</button><input id="guideFile" type="file" accept="audio/*" hidden><span id="guideStatus" class="muted">No guide selected.</span></div><details id="analysisDetails"><summary>Analysis Details</summary><div class="row"><b id="stageName">Idle</b><progress id="overall" max="100" value="0"></progress></div><div class="analysis-split"><section class="analysis-scroll"><b>Console</b><div id="liveLog"></div></section><section class="analysis-scroll"><h3>Live Transcript</h3><div id="transcript" class="muted">Transcript will appear during analysis.</div><div id="visualPlanDetails" class="muted">Concrete visual plan will appear after sourcing.</div></section></div></details></section>

<div class="grid"><aside class="rail"><b>PHRASES</b><div class="row"><button data-filter="all">All</button><button data-filter="needs">Needs Choice</button><button data-filter="selected">Selected</button><button data-filter="none">NO BROLL</button><button data-filter="errors">Errors</button></div><div id="phrases"><p class="muted">Analyze a source to begin.</p></div></aside><section class="stage"><div id="active" class="muted">No project artifacts loaded.</div><h3>VIDEO SUGGESTIONS</h3><div id="videos" class="cards"></div><h3>IMAGE SUGGESTIONS</h3><div id="images" class="cards"></div></section><aside class="tray"><b>ORDERED SELECTION</b><div id="selected"></div><button id="none" disabled>NO BROLL</button><button id="confirm" class="primary" disabled>CONFIRM PLAN</button><p id="notice" class="muted">Analyze a reel first.</p></aside></div></main><dialog id="lightbox"><button id="closeLightbox">Close</button><img id="lightboxImage" hidden><video id="lightboxVideo" controls hidden></video></dialog>

<script>(()=>{'use strict';const $=id=>document.getElementById(id),state={pid:null,project:null,data:{chunks:[]},active:null,filter:'all',sel:new Map(),run:null,poll:null},api=async(p,o)=>{const r=await fetch('/api/curation'+p,o),j=await r.json();if(!r.ok)throw Error(j.detail||'Request failed');return j},esc=x=>String(x??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));

async function project(){if(!state.pid){state.project=await api('/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:'{"name":"New Reel"}'});state.pid=state.project.project_id}return state.pid}function show(p,name,url){state.project=p;const v=p.source_video;$('analyze').disabled=!v;$('originalGuide').disabled=!v?.has_audio;$('replaceGuide').disabled=!v;if(v){$('source').src=url;$('source').hidden=false;$('metadata').textContent=`${name} · ${v.duration}s · ${v.fps}fps · ${v.width}×${v.height} · audio ${v.has_audio?'yes':'no'}`}const g=p.guide_audio;$('guideStatus').textContent=g?`${g.mode} guide · ${g.duration}s${p.guide_duration_warning?' · '+p.guide_duration_warning:''}`:'No guide selected.'}

async function upload(f){const p=await api(`/projects/${await project()}/source/upload?filename=${encodeURIComponent(f.name)}`,{method:'PUT',body:f});show(p,f.name,URL.createObjectURL(f))}async function local(){const p=await api(`/projects/${await project()}/source/local`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path:$('local').value})}),v=p.source_video;show(p,v.path.split(/[\\/]/).pop(),`/api/curation/projects/${state.pid}/media/source-video/source`)}function status(c){const v=state.sel.get(c.id);return c.error?'Error':v==='NO_BROLL'?'NO BROLL':Array.isArray(v)&&v.length?'Selected':'Needs Choice'}function card(a){const chosen=state.sel.get(state.active),selected=Array.isArray(chosen)&&chosen.includes(a.asset_id),m=a.kind==='video'&&a.preview_status==='ready'?`<video controls src="${esc(a.preview_url)}" poster="${esc(a.poster_url)}"></video>`:`<img src="${esc(a.preview_url)}">`;return `<article class="card ${selected?'active':''}" data-a="${esc(a.asset_id)}">${m}<div class="copy"><b>${esc(a.title||a.provider)}</b><small>${esc(a.provider)} · ${esc(a.rights_state)}${a.kind==='video'&&a.preview_status!=='ready'?' · Discovery — thumbnail only':''}</small><a href="${esc((a.source_page||'').startsWith('https://')||(a.source_page||'').startsWith('http://')?a.source_page:'#')}" target="_blank" rel="noopener noreferrer">Open source</a><button class="select">${selected?'Deselect':'Select'}</button></div></article>`}

function inspectMedia(media){const video=media.tagName==='VIDEO',target=video?$('lightboxVideo'):$('lightboxImage'),other=video?$('lightboxImage'):$('lightboxVideo');other.hidden=true;target.hidden=false;target.src=media.currentSrc||media.src;$('lightbox').showModal();if(video)target.play().catch(()=>{})}function planDetails(p){if(!p)return 'Concrete visual plan will appear after sourcing.';const shots=(p.shots||[]).map(s=>`<li><b>${esc(s.shot_id||'shot')}</b> · ${esc(s.description||'')}<br><small>Image: ${esc((s.image_queries||[]).join(' · '))}<br>Video: ${esc((s.video_queries||[]).join(' · '))}</small></li>`).join('');const diag=k=>{const d=p[k];if(!d)return '';const chosen=(d.selected||[]).map(x=>`${x.shot_id||'shot'}: ${x.query||''} [${x.qwen_score??x.score??'n/a'}]`).join(' · ');return `<p><b>${esc(k)}</b> · providers ${esc((d.providers||[d.provider||'n/a']).join(' · '))} · raw ${esc(d.raw??d.raw_results??0)} · accepted ${esc(d.accepted??0)}${d.zero_result_reason?` · zero: ${esc(d.zero_result_reason)}`:''}${chosen?`<br><small>Qwen: ${esc(chosen)}</small>`:''}</p>`};return `<h3>Concrete Visual Plan</h3><p><b>Editorial function:</b> ${esc(p.editorial_function)}<br><b>Core meaning:</b> ${esc(p.core_meaning)}<br><b>Subtext:</b> ${esc(p.subtext)}<br><b>Mode:</b> ${esc(p.visual_mode)}<br><b>Avoid:</b> ${esc((p.avoid||[]).join(' · '))}</p><ol>${shots}</ol>${diag('image_search')}${diag('video_search')}`}function draw(){const all=state.data.chunks||[],shown=all.filter(c=>state.filter==='all'||(state.filter==='none'?status(c)==='NO BROLL':state.filter==='selected'?status(c)==='Selected':state.filter==='errors'?status(c)==='Error':status(c)==='Needs Choice'));$('phrases').innerHTML=shown.length?shown.map(c=>`<button class="phrase ${c.id===state.active?'active':''}" data-c="${esc(c.id)}"><small>${status(c)}</small>${esc(c.text||c.id)}</button>`).join(''):'<p class="muted">No phrases in this view.</p>';document.querySelectorAll('[data-c]').forEach(b=>b.onclick=()=>{state.active=b.dataset.c;draw()});const c=all.find(x=>x.id===state.active);$('none').disabled=!c;$('visualPlanDetails').innerHTML=planDetails(c?.visual_plan);if(!c){$('active').textContent='No project artifacts loaded.';$('videos').innerHTML='';$('images').innerHTML='';$('selected').innerHTML=''}else{$('active').innerHTML=`<h2>${esc(c.text||c.id)}</h2>`;$('videos').innerHTML=c.assets.filter(a=>a.kind==='video').slice(0,3).map(card).join('')|| `<p class="muted">${esc(c.video_reason||'No video suggestions.')}</p>`;$('images').innerHTML=c.assets.filter(a=>a.kind==='image').slice(0,4).map(card).join('')|| `<p class="muted">${esc(c.image_reason||'No image suggestions.')}</p>`;document.querySelectorAll('.card').forEach(node=>{const media=node.querySelector('video,img');media.onclick=()=>inspectMedia(media);node.querySelector('.select').onclick=()=>pick(c.id,node.dataset.a)});const v=state.sel.get(c.id),ids=Array.isArray(v)?v:[];$('selected').innerHTML=v==='NO_BROLL'?'<b>NO BROLL</b>':ids.map((id,i)=>`<div class="chip"><b>V${i+2}</b><span>${esc(id)}</span><button data-m="-1" data-i="${i}" ${i===0?'disabled':''}>↑</button><button data-m="1" data-i="${i}" ${i===ids.length-1?'disabled':''}>↓</button><button data-x="${esc(id)}">×</button></div>`).join('');document.querySelectorAll('[data-m]').forEach(b=>b.onclick=()=>move(+b.dataset.i,+b.dataset.m));document.querySelectorAll('[data-x]').forEach(b=>b.onclick=()=>pick(c.id,b.dataset.x))}const left=all.filter(c=>{const v=state.sel.get(c.id);return v!=='NO_BROLL'&&(!Array.isArray(v)||!v.length)}).length;$('findVideos').disabled=!all.length;$('findImages').disabled=!all.length;$('confirm').disabled=!all.length||left>0;$('notice').textContent=all.length?(left?`${left} phrases still need a decision.`:'All phrases are planned.'):'Analyze a reel first.'}

async function save(cid){$('save').textContent='Saving…';const v=state.sel.get(cid);await api(`/projects/${state.pid}/curation/chunks/${encodeURIComponent(cid)}/selection`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({asset_ids:v==='NO_BROLL'?[]:v||[],no_broll:v==='NO_BROLL'})});$('save').textContent='Saved'}async function pick(cid,id){let a=state.sel.get(cid);a=Array.isArray(a)?a:[];state.sel.set(cid,a.includes(id)?a.filter(x=>x!==id):[...a,id]);await save(cid);draw()}async function move(i,d){const a=[...(state.sel.get(state.active)||[])],j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];state.sel.set(state.active,a);await save(state.active);draw()}async function hydrate(){state.data=await api(`/projects/${state.pid}/curation`);state.sel.clear();for(const [id,v] of Object.entries(state.data.selection_plan?.chunks||{}))state.sel.set(id,v.no_broll?'NO_BROLL':v.selected_assets.map(x=>x.asset_id));state.active=state.data.chunks[0]?.id||null;draw()}async function watch(id){state.run=id;$('stop').hidden=false;$('analysisDetails').open=true;state.poll=setInterval(async()=>{const r=await fetch(`/v1/debug/runs/${id}`).then(x=>x.json());$('runStatus').textContent=`${r.status} · ${r.total_progress}%`;$('stageName').textContent=`${r.stage_type}: ${r.last_message}`;$('overall').value=r.total_progress;$('liveLog').innerHTML=(r.events||[]).slice(-100).map(e=>`<details><summary>[${esc(e.stage)}] ${esc(e.message)} ${e.progress==null?'':Math.round(e.progress)+'%'} ${esc(e.data?.provider||e.data?.providers?.join(' · ')||'')} ${esc(e.data?.query||'')}</summary><pre>${esc(JSON.stringify(e.data||{},null,2))}</pre></details>`).join('');const planned=(r.events||[]).filter(e=>e.stage==='visual_planning'&&e.data?.shots).at(-1);if(planned)$('visualPlanDetails').innerHTML=planDetails(planned.data);if(r.stage_type==='analyze'){if(r.transcript_status==='active'){const t=await api(`/projects/${state.pid}/transcript`);$('transcript').textContent=(t.segments||[]).map(s=>s.text).join(' ')||'Transcribing...'}else if(r.transcript_status==='failed'){$('transcript').textContent=`Analysis failed before ASR: ${r.transcript_message||r.last_message}`}else{$('transcript').textContent='Waiting for ASR worker...'}}if(['SUCCEEDED','FAILED','CANCELLED'].includes(r.status)){clearInterval(state.poll);state.run=null;$('stop').hidden=true;$('overall').value=r.total_progress;if(r.status==='SUCCEEDED')await hydrate()}},500)}async function startStage(path){const r=await api(`/projects/${state.pid}/${path}`,{method:'POST'});r.status==='started'?await watch(r.run_id):await hydrate()}

$('choose').onclick=()=>$('file').click();$('file').onchange=()=>{const f=$('file').files[0];if(f)upload(f)};$('path').onclick=()=>{$('local').hidden=!$('local').hidden;$('loadPath').hidden=$('local').hidden};$('loadPath').onclick=local;$('originalGuide').onclick=async()=>show(await api(`/projects/${state.pid}/guide/original`,{method:'POST'}),$('metadata').textContent.split(' · ')[0],$('source').src);$('replaceGuide').onclick=()=>$('guideFile').click();$('guideFile').onchange=async()=>{const f=$('guideFile').files[0];if(f)show(await api(`/projects/${state.pid}/guide/upload?filename=${encodeURIComponent(f.name)}`,{method:'PUT',body:f}),$('metadata').textContent.split(' · ')[0],$('source').src)};$('analyze').onclick=()=>startStage('analyze');$('findVideos').onclick=()=>startStage('source/videos');$('findImages').onclick=()=>startStage('source/images');$('stop').onclick=async()=>{if(state.run)await fetch(`/v1/debug/runs/${state.run}/cancel`,{method:'POST'})};$('none').onclick=async()=>{state.sel.set(state.active,'NO_BROLL');await save(state.active);draw()};$('confirm').onclick=()=>{$('notice').textContent='Plan confirmed and saved.'};$('closeLightbox').onclick=()=>{$('lightboxVideo').pause();$('lightboxVideo').removeAttribute('src');$('lightbox').close()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;draw()});const drop=$('drop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');const f=e.dataTransfer.files[0];if(f)upload(f)};draw()})();</script></html>'''.replace("__BUILD_MARKER__", marker).replace("__BUILD_SENTINEL__", sentinel)

